194	// IsRelativeTraversal reports whether rel escapes its base directory.
195	// It accepts both OS-native paths and Git-style slash-normalized paths.
196	func IsRelativeTraversal(rel string) bool {
197		return rel == ".." || strings.HasPrefix(rel, "../") || strings.HasPrefix(rel, `..\`)
198	}
199	
200	// ToRelativePath converts an absolute path to relative.
201	// Returns empty string if the path is outside the working directory.
202	func ToRelativePath(absPath, cwd string) string {
203		absPath = normalizeMSYSPath(absPath)
204		cwd = normalizeMSYSPath(cwd)
205	
206		// On Windows, MSYS/Git Bash sometimes omits the drive letter, producing
207		// paths like /Users/... that filepath.IsAbs doesn't recognize. Prepend
208		// the drive letter from cwd so filepath.Rel can match them.
209		if runtime.GOOS == osWindows && len(absPath) > 0 && absPath[0] == '/' && len(cwd) >= 2 && cwd[1] == ':' {
210			absPath = cwd[:2] + absPath
211		}
212	
213		if !filepath.IsAbs(absPath) {
214			return absPath
215		}
216		relPath, err := filepath.Rel(cwd, absPath)
217		if err != nil || IsRelativeTraversal(relPath) {
218			return ""
219		}
220	
221		return relPath
222	}
223	
224	// normalizeMSYSPath converts MSYS/Git Bash-style paths (e.g., /c/Users/...)
225	// to Windows-style paths (e.g., C:/Users/...) so that filepath.IsAbs and
226	// filepath.Rel work correctly. On non-Windows platforms this is a no-op.
