+	}
+	modules := gogitconfig.NewModules()
+	if err := modules.Unmarshal(data); err != nil {
+		return nil
+	}
+	out := make(map[string]struct{}, len(modules.Submodules))
+	for _, sub := range modules.Submodules {
+		if sub != nil && sub.Path != "" {
+			out[path.Clean(filepath.ToSlash(sub.Path))] = struct{}{}
+		}
+	}
+	return out
+}
